INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-posty-swe206', 'stk-posty', 'SWE 206', 'doc', '{"docs": [{"id": "stk-dr-f99239", "n": "Dr. Jameleddine Hassine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "SWE 206 -211\n\nالتحضير :ورقة تمر على الطلاب لو تجي متاخر عادي تحضر نفسك\nطريقة الشرح : اتعب وانا امدح شرحة الدكتور فاهم ويفصل ويوضح كل نقطه ومايقصر ابد في الشرح\nالكويزات : عبارة عن true/false-MCQ\nالمياجر:ميد كومن\nالفاينلات :كومن\nالقريد النهائي:A+++++++\nالصوت:واضح ولغته جدا جميله\nإضافات :يكفي ان الطلاب جلسوا يسالونه وش الكورسات الي تبي تدرسها الترم الجاي علشان ينزلونها معه، اذا الدكتور موجود يستاهل يكون خيارك الاول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532694-swe206", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameleddine-hassine/99239/6", "user": "Posty", "ts": 1636487216000, "tid": 99239, "pn": 6}}]}', 1636487216000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-swe206', 'stk-mohammed_mag', 'SWE 206', 'doc', '{"docs": [{"id": "stk-dr-f182898", "n": "Dr. Abdulmjeed Al-Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: SWE 206 LAB \" نص ترم فقط وتغير \"\n\nالتحضير : كل كلاس يحضر\n\nطريقة الشرح : يتكلم بسرعه شوي , بس مايقصر الا حبيت تسأل ويعيد شوي\n\nالكويزات : لا يوجد\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\n*الصوت: واضح لكن سريع جدا *\n\nإضافات : الدكتور جدا حبيب ويحاول يفيد الطلاب بالكورس ويمكن امور متعلقه بالتخصص اكثر ك \" سوفتوير \" وأيضا متعاون من ناحيه الديدلاين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533310-swe206", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulmjeed-al-othman/182898/3", "user": "Mohammed_Mag", "ts": 1641337115000, "tid": 182898, "pn": 3}}, {"id": "stk-dr-f118624", "n": "Dr. Mahmoud Niazi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: SWE 206 - LECTURE - TERM 211\n\nالتحضير : يحضر اخر الكلاس بالسيريال نمبر , ومايخصم على التأخير\n\nطريقة الشرح : مره صعب تفهم , لهجه باكستانيه , يمكن بتحس انه متسرع لأن الكورس فعلا جدا دسم وثقييييل ,\n\nالكويزات : سهله جدا\n\nالمياجر: يوجد ميد كومن متوسط الصعوبه والوقت ضيق\n\nالفاينلات : الفاينل كومن ايضا\n\nالقريد النهائي: A\n\nالصوت: لهجه غير واضحه\n\nإضافات : الدكتور مسك الكورس نص الترم , والنص الثانيه كمله دكتور أخر .\nلهجته مره سيئه بصراحه صعب تفهم , لكن ياخذ الاساله وحبيب بالتعامل , تقدر تقاطعه ويرد عليك بأقصى مايمكن .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533311-swe206", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-niazi/118624/8", "user": "Mohammed_Mag", "ts": 1641337311000, "tid": 118624, "pn": 8}}, {"id": "stk-dr-f181226", "n": "Dr. Y Hassan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: SWE 206 - LAB - TERM 211\n\nالتحضير : يحضر اخر الكلاس بالسيريال بالاسم , ومايخصم على التأخير\n\nطريقة الشرح : لهجه صعب تفهم شوي , بس اذا ركزت معه بتفهم وش يبي اللاب .\n\nالكويزات : لايوجد\n\nالمياجر: يوجد ميد كومن متوسط الصعوبه والوقت ضيق\n\nالفاينلات : الفاينل كومن ايضا\n\nالقريد النهائي: A\n\nالصوت: لهجه غير واضحه\n\nإضافات : الدكتور مسك الكورس النص الثاني من الترم . وحبيب يأجل الديدلاين .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533312-swe206", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/y-hassan/181226/8", "user": "Mohammed_Mag", "ts": 1641337516000, "tid": 181226, "pn": 8}}]}', 1641337115000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar-12232-swe206', 'stk-omar-12232', 'SWE 206', 'doc', '{"docs": [{"id": "stk-dr-f182898", "n": "Dr. Abdulmjeed Al-Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "SWE206 (LAB) - TERM 212\n\nالتحضير : ينادي الأسماء بكل لاب.\nطريقة الشرح : يقرا من السلايدات حقت اللاب ويجيب امثلة من الواقع.\nالقريد النهائي: +A\nالصوت: واضح.\nإضافات : الدكتور خلوق جدا وشرحه اسطوري ويحفظ طلابه ويتواصل معهم ينصح به وبشدة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534553-swe206", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulmjeed-al-othman/182898/4", "user": "Omar-12232", "ts": 1654317972000, "tid": 182898, "pn": 4}}]}', 1654317972000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
